"""Reading and writing the pattern/IPC TOML format plus ``versions.json``.

Upstream format (one file per DLL build, named ``<sha256>.toml``)::

    # MACHINE-GENERATED by ... - do not hand-edit

    [0xD05E26A2]
    name = "AddProtobufAsBinary"
    rva = "0xA14DF0"
    sig = "40 53 55 56 57 ..."

The hex table key is a stable hash of the hook name (see :func:`hook_key`) so
the section ordering is reproducible and diffs stay small.
"""

from __future__ import annotations

import json
import tomllib
from dataclasses import dataclass
from pathlib import Path

GENERATED_HEADER = "# MACHINE-GENERATED by tools/pattern-tracker - do not hand-edit"


@dataclass(frozen=True)
class PatternEntry:
    name: str
    rva: int
    sig: str


def hook_key(name: str) -> str:
    """Table key for a hook name: FNV-1a 32-bit, ``0x%08X``.

    Reverse-engineered from published feeds *and* confirmed against the loader:
    ``OpenSteamTool.dll`` looks patterns up by this key, so a wrong key makes the
    whole file load and then resolve to nothing
    (``PatternLoader: no entry for 'GetAppByID' (key=0x3FC68546)``).
    Verified on 15 name/key pairs before this function was written.
    """
    digest = 0x811C9DC5  # FNV offset basis
    for byte in name.encode():
        digest ^= byte
        digest = (digest * 0x01000193) & 0xFFFFFFFF  # FNV prime
    return f"0x{digest:08X}"


def load_pattern(path: str | Path) -> dict[str, PatternEntry]:
    """Parse a pattern TOML into ``{name: PatternEntry}``."""
    raw = tomllib.loads(Path(path).read_text(encoding="utf-8"))
    out: dict[str, PatternEntry] = {}
    for _key, table in raw.items():
        if not isinstance(table, dict):
            continue
        name = table.get("name")
        rva = table.get("rva")
        sig = table.get("sig")
        if not (isinstance(name, str) and isinstance(rva, str) and isinstance(sig, str)):
            continue
        out[name] = PatternEntry(name=name, rva=int(rva, 16), sig=sig.strip().upper())
    return out


def dump_pattern(entries: list[PatternEntry]) -> str:
    """Serialise entries in a stable, upstream-compatible layout."""
    lines = [GENERATED_HEADER, ""]
    for entry in sorted(entries, key=lambda e: e.name):
        lines.append(f"[{hook_key(entry.name)}]")
        lines.append(f'name = "{entry.name}"')
        lines.append(f'rva = "0x{entry.rva:X}"')
        lines.append(f'sig = "{entry.sig}"')
        lines.append("")
    return "\n".join(lines)


def load_versions(path: str | Path) -> dict:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def dump_versions(data: dict) -> str:
    return json.dumps(data, indent=2, sort_keys=True) + "\n"
